def generalized_binomial(x, k):
    if k < 0:
        return 0.0
    res = 1.0
    for i in range(1, k + 1):
        res *= (x - i + 1) / i
    return float(res)

from itertools import combinations

def unique_combinations(nums, k):
    if k < 0 or k > len(nums):
        return []
    s_nums = sorted(nums)
    return sorted(list(set(combinations(s_nums, k))))

def count_derangements(n):
    if n < 0:
        return None
    if n == 0:
        return 1
    a, b = 1, 0
    for i in range(2, n + 1):
        a, b = b, (i - 1) * (a + b)
    return b

def stirling_second(n, k):
    if n < 0 or k < 0 or k > n:
        return 0
    if n == 0 and k == 0:
        return 1
    if k == 0:
        return 0
    return k * stirling_second(n - 1, k) + stirling_second(n - 1, k - 1)

from itertools import combinations

def unique_power_set(nums):
    s = sorted(nums)
    res = set()
    for r in range(len(s) + 1):
        res.update(combinations(s, r))
    return sorted(res, key=lambda x: (len(x), x))

from itertools import permutations

def kth_unique_permutation(nums, k):
    if k < 0:
        return None
    perms = sorted(set(permutations(sorted(nums))))
    return perms[k] if k < len(perms) else None

def bounded_partitions(n, k):
    if n < 0 or k < 0 or (n > 0 and k == 0):
        return []
    if n == 0:
        return [()]
    def gen(rem, max_val, parts):
        if rem == 0:
            return [()]
        if parts == 0:
            return []
        return [(i,) + p for i in range(1, min(rem, max_val) + 1) for p in gen(rem - i, i, parts - 1)]
    return sorted(gen(n, n, k))

import math

def stars_and_bars(n, k):
    if n < 0 or k < 0:
        return 0
    if n == 0 and k == 0:
        return 1
    if k == 0:
        return 0
    return math.comb(n + k - 1, k - 1)

def permutation_parity(p):
    if sorted(p) != list(range(len(p))):
        return None
    inversions = sum(p[i] > p[j] for i in range(len(p)) for j in range(i + 1, len(p)))
    return 1 if inversions % 2 == 0 else -1

def count_unique_sum_pairs(nums, k):
    pairs = set()
    seen = set()
    for x in nums:
        if k - x in seen:
            pairs.add((min(x, k - x), max(x, k - x)))
        seen.add(x)
    return len(pairs)

def least_frequent_last(nums):
    if not nums:
        return None
    counts = {}
    last_idx = {}
    for i, x in enumerate(nums):
        counts[x] = counts.get(x, 0) + 1
        last_idx[x] = i
    return min(counts, key=lambda x: (counts[x], -last_idx[x]))

def invert_frequent_values(d):
    inv = {}
    for k, v in d.items():
        inv.setdefault(v, []).append(k)
    return {v: sorted(ks) for v, ks in inv.items() if len(ks) >= 2}

def merge_non_zero(d1, d2):
    res = dict(d1)
    for k, v in d2.items():
        res[k] = res.get(k, 0) + v
    return {k: v for k, v in res.items() if v != 0}

def second_highest_freq(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    freqs = sorted(set(counts.values()), reverse=True)
    return freqs[1] if len(freqs) >= 2 else None

def count_pair_sums(nums, k):
    seen = {}
    count = 0
    for x in nums:
        count += seen.get(k - x, 0)
        seen[x] = seen.get(x, 0) + 1
    return count

def rank_alpha_chars(s):
    counts = {}
    for c in s.lower():
        if c.isalpha():
            counts[c] = counts.get(c, 0) + 1
    return sorted(counts.items(), key=lambda x: (-x[1], x[0]))

def elements_in_multiple_lists(lists):
    counts = {}
    for lst in lists:
        for x in set(lst):
            counts[x] = counts.get(x, 0) + 1
    return sorted(k for k, v in counts.items() if v >= 2)

def index_span_dict(nums):
    first = {}
    span = {}
    for i, x in enumerate(nums):
        if x in first:
            span[x] = i - first[x]
        else:
            first[x] = i
    return span

def key_with_max_mean(d):
    valid = {k: sum(v) / len(v) for k, v in d.items() if v}
    if not valid:
        return None
    return min(valid, key=lambda k: (-valid[k], k))

def diff_multiset_counts(target, actual):
    counts = {}
    for x in target:
        counts[x] = counts.get(x, 0) + 1
    for x in actual:
        counts[x] = counts.get(x, 0) - 1
    missing = sum(v for v in counts.values() if v > 0)
    extra = sum(-v for v in counts.values() if v < 0)
    return (missing, extra)

def count_weekdays_in_range(start, end, weekdays):
    if start > end or not weekdays:
        return 0
    valid = {w % 7 for w in weekdays}
    total_days = end - start + 1
    full_weeks, rem = divmod(total_days, 7)
    extra = sum(1 for i in range(rem) if (start + i) % 7 in valid)
    return full_weeks * len(valid) + extra

def shift_month(month, offset):
    year_shift, new_month_zero = divmod(month - 1 + offset, 12)
    return (new_month_zero + 1, year_shift)

def count_leap_years(start, end):
    if start > end:
        return 0
    def leaps_before(y):
        return y // 4 - y // 100 + y // 400
    return leaps_before(end) - leaps_before(start - 1)

def shortest_weekday_distance(a, b):
    diff = (b - a) % 7
    return diff if diff <= 3 else diff - 7

def day_of_year_to_month_day(day_of_year, month_lengths):
    if day_of_year < 1 or not month_lengths:
        return None
    for m, length in enumerate(month_lengths, 1):
        if day_of_year <= length:
            return (m, day_of_year)
        day_of_year -= length
    return None

def cycle_days_in_month(n, s, k):
    if n < 1 or k <= 0 or s > n:
        return [s] if (k == 0 and 1 <= s <= n) else []
    first = s if s >= 1 else s + ((1 - s + k - 1) // k) * k
    return list(range(first, n + 1, k))

def normalize_dhms(d, h, m, s):
    total_seconds = ((d * 24 + h) * 60 + m) * 60 + s
    days, rem = divmod(total_seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, seconds = divmod(rem, 60)
    return (days, hours, minutes, seconds)

def interval_overlap_days(s1, e1, s2, e2):
    if s1 > e1 or s2 > e2:
        return 0
    return max(0, min(e1, e2) - max(s1, s2) + 1)

def most_frequent_weekdays(offsets):
    if not offsets:
        return []
    counts = [0] * 7
    for o in offsets:
        counts[o % 7] += 1
    max_c = max(counts)
    return [w for w, c in enumerate(counts) if c == max_c]

def smallest_prime_factor(n):
    n = abs(n)
    if n < 2:
        return None
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return i
    return n

def list_gcd(nums):
    import math
    res = 0
    for x in nums:
        res = math.gcd(res, x)
    return res

def is_perfect_square(n):
    import math
    if n < 0:
        return False
    root = math.isqrt(n)
    return root * root == n

def positive_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return tuple(sorted(divs))

def mod_inverse(a, m):
    if m == 1:
        return 0
    for x in range(m):
        if (a * x) % m == 1:
            return x
    return None

def is_power_of(n, b):
    if n == 1:
        return True
    if b in (0, 1) or (b == -1 and n != -1) or n == 0:
        return n == b
    while n % b == 0:
        n //= b
    return n == 1

def digital_root(n):
    if n == 0:
        return 0
    return 1 + (n - 1) % 9

def is_abundant(n):
    if n < 2:
        return False
    total = 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            total += i + (n // i if i * i != n else 0)
    return total > n

def min_subset_gt_k(nums, k):
    res, current = [], 0
    for x in sorted(nums, reverse=True):
        if current > k:
            return res
        if x <= 0 and current <= k:
            break
        res.append(x)
        current += x
    return res if current > k else None

def greedy_coin_change(coins, amount):
    res = []
    for c in sorted(set(coins), reverse=True):
        if c > 0 and amount >= c:
            count, amount = divmod(amount, c)
            res.extend([c] * count)
    return tuple(res) if amount == 0 else None

def max_sum_after_negations(nums, k):
    if not nums:
        return 0
    nums = sorted(nums)
    for i in range(len(nums)):
        if nums[i] < 0 and k > 0:
            nums[i], k = -nums[i], k - 1
    return sum(nums) - (2 * min(nums) if k % 2 else 0)

def min_max_pair_sum(nums):
    if not nums:
        return None
    s = sorted(nums)
    n = len(s)
    return max(s[i] + s[n - 1 - i] for i in range(n // 2))

def min_jumps_to_end(nums):
    if len(nums) <= 1:
        return 0 if nums else -1
    jumps = cur_end = cur_far = 0
    for i in range(len(nums) - 1):
        cur_far = max(cur_far, i + nums[i])
        if i == cur_end:
            jumps, cur_end = jumps + 1, cur_far
    return jumps if cur_end >= len(nums) - 1 else -1

def fractional_knapsack(items, W):
    ans = 0.0
    rem = max(0, W)
    for v, w in sorted(items, key=lambda x: float('inf') if x[1] == 0 else x[0] / x[1], reverse=True):
        if v > 0:
            take = 1.0 if w == 0 else min(1.0, rem / w)
            ans, rem = ans + v * take, rem - w * take
    return round(float(ans), 2)

def min_boats(people, limit):
    if not people:
        return 0
    p = sorted(people)
    if p[-1] > limit:
        return None
    i, j, boats = 0, len(p) - 1, 0
    while i <= j:
        i += (p[i] + p[j] <= limit)
        j, boats = j - 1, boats + 1
    return boats

def first_fit_bins(items, C):
    bins, sums = [], []
    for x in items:
        if x > C:
            return None
        idx = next((i for i, s in enumerate(sums) if s + x <= C), len(bins))
        if idx == len(bins):
            bins.append([])
            sums.append(0)
        bins[idx].append(x)
        sums[idx] += x
    return bins
